local _, ns = ...
local Translate = ns.Lore.Translate

Translate("deDE", "arathi-highlands", {
	title = "Arathihochland",
	aliases = { "Arathi" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Das Arathihochland ist ein hohes, trockenes Land aus Gras, Wind und grauem Stein zwischen dem {link:hillsbrad-foothills}Vorgebirge von Hillsbrad{/link} und dem {link:the-hinterlands}Hinterland{/link}. Hier wurde die Menschheit zum ersten Mal zu einer Nation. Die Festung {link:stromgarde-keep}Strom{/link} erhob sich auf diesen Ebenen, als die Stämme der {link:humans}Menschen{/link} noch mit den Trollen im Krieg lagen, und jedes Menschenreich der Welt stammt von ihr ab. Heute gehört das Hochland niemandem. Stromgarde, das Königreich, das Stroms Namen bewahrte, ist zu Ruinen zerfallen. Die {link:orcs}Orcs{/link} halten {link:hammerfall}Hammerfall{/link} auf den östlichen Hügeln, auf eben dem Boden, auf dem die {link:alliance}Allianz{/link} sie einst in Ketten hielt. Die letzten Soldaten Stromgardes warten in der Zuflucht auf den Tag, an dem sie heimkehren können.]=],
		},
		{
			title = "Ursprünge",
			text = [=[Etwa achtundzwanzig Jahrhunderte vor dem {link:dark-portal}Dunklen Portal{/link} waren die Menschenstämme des Nordens verstreut und bekriegten einander, und die {link:trolls}Trolle{/link} der Amani machten Jagd auf sie alle. {link:thoradin}Thoradin{/link}, Kriegsherr des Stammes der Arathi, einte die Stämme und errichtete in diesem Hochland die Festung {link:stromgarde-keep}Strom{/link}. Das offene, dürre Land verwehrte den Trollen die Hinterhalte im Wald, die sie bevorzugten. In Strom lehrten die Elfen von {link:quel-thalas}Quel'Thalas{/link} hundert {link:humans}Menschen{/link} die Wege der {link:arcane-magic}Magie{/link}, und gemeinsam zerschlugen die beiden Völker die Amani in den {link:troll-wars}Trollkriegen{/link}. In späteren Jahrhunderten breitete sich das Reich {link:arathor}Arathor{/link} über den Kontinent aus und ließ seine erste Stadt zurück. Die großen Familien zogen nach Norden, und die Letzten aus Thoradins Linie segelten nach Süden, um das Reich zu gründen, das zu {link:stormwind-city}Stormwind{/link} wurde. Die Trollbanes, Erben eines Generals der Trollkriege, blieben. Sie nannten die alte Stadt Stromgarde.]=],
		},
		{
			title = "Die Gegenwart",
			text = [=[{link:thoras-trollbane}König Thoras{/link} Trollbane ist tot, und seine Stadt liegt in Trümmern. {link:boulderfist-ogres}Felsfaustoger{/link} und die Banditen des {link:syndicate}Syndikats{/link} halten den größten Teil Stromgardes, und der Rest seines Heeres klammert sich unter {link:prince-galen-trollbane}Prinz Galen Trollbane{/link} an ein einziges Viertel. In der Zuflucht sammelt {link:captain-nials}Hauptmann Nials{/link}, was an Kraft geblieben ist, und der Bund von {link:arathor}Arathor{/link} bereitet sich darauf vor, das Land mit Gewalt zurückzuerobern. Im Osten ist {link:hammerfall}Hammerfall{/link} zu einem Außenposten der {link:horde}Horde{/link} geworden. Seine {link:orcs}Orcs{/link} wehren sich gegen {link:witherbark-trolls}Witherbarktrolle{/link} und Felsfaustoger, die sich gegen sie verbündet haben. {link:darkspear-trolls}Darkspear{/link}-Jäger, von {link:vol-jin}Vol'jin{/link} gesandt, suchen ein uraltes Schwert im Grab der Trollbanes, und die Entweihten der Verlassenen kämpfen um das reiche Tal des Arathibeckens. Unter der Erde ruft eine Stimme durch Kristallsplitter und fleht um Freiheit.]=],
		},
		{
			title = "Bewohner",
			text = [=[• {b}Die Soldaten Stromgardes.{/b} Das letzte Heer des Königreichs, geteilt zwischen den Ruinen ihrer {link:capital-city}Hauptstadt{/link} und dem Lager in der Zuflucht.
• {b}Die {link:horde}Horde{/link} von {link:hammerfall}Hammerfall{/link}.{/b} {link:orcs}Orcs{/link}, {link:darkspear-trolls}Darkspeartrolle{/link} und {link:forsaken}Verlassene{/link}, im Krieg mit jeder anderen Macht des Hochlands.
• {b}Das {link:syndicate}Syndikat{/link}.{/b} Diebe und Hexenmeister im Dienst der gefallenen Lords von {link:alterac-mountains}Alterac{/link}.
• {b}Die {link:boulderfist-ogres}Felsfaustoger{/link}.{/b} Das größte Heer des Hochlands, von {link:boulder-gor}Fels'gor{/link} bis zur {link:boulderfist-hall}Halle der Felsfäuste{/link}.
• {b}Die {link:witherbark-trolls}Witherbarktrolle{/link}.{/b} Waldtrolle des Südostens, die ältesten Feinde Stroms.
• {b}Die {link:drywhisker-kobolds}Trockenstoppelkobolde{/link}.{/b} Gräber der östlichen Schlucht und Verbündete der Riesen.
• {b}Die Schwarzmeerräuber.{/b} Piraten aus {link:booty-bay}Booty Bay{/link}, gestrandet in der Faldirbucht.]=],
		},
		{
			title = "Geschichte",
			text = [=[• {b}{link:arathor}Arathor{/link}.{/b} {link:thoradin}Thoradin{/link} einte die Stämme und errichtete {link:stromgarde-keep}Strom{/link}. Von hier zog die Menschheit aus, um ihre Königreiche zu gründen.
• {b}Die Sieben Königreiche.{/b} Als Strom verfiel, gingen seine Adligen und seine Königslinie fort. Die Trollbanes blieben und herrschten über Stromgarde.
• {b}Der Zweite Krieg.{/b} {link:thoras-trollbane}Thoras Trollbane{/link} führte Stromgarde in die {link:alliance}Allianz{/link} von {link:lordaeron}Lordaeron{/link}.
• {b}Die Lager.{/b} Nach dem Krieg hielt die Allianz besiegte {link:orcs}Orcs{/link} in einem Lager in den östlichen Hügeln gefangen. {link:thrall}Thrall{/link} und {link:orgrim-doomhammer}Orgrim Doomhammer{/link} brachen es auf, und Doomhammer fiel dort.
• {b}Der Fall.{/b} Nach dem Fall Lordaerons fiel Stromgarde an {link:ogres}Oger{/link} und Banditen, und sein Volk wurde zerstreut.]=],
		},
		{
			title = "Überlieferungen des Hochlands",
			text = [=[• Vier Kreise aus aufrechten Steinen stehen verteilt im Hochland. Geister der Erde, des Feuers, des Wassers und der Luft wandeln zwischen ihnen.
• Die Soldaten der Zuflucht haben geschworen, das Hochland nicht zu verlassen, bis das Banner des Königs wieder über {link:stromgarde-keep}Stromgarde{/link} weht.
• Die {link:orcs}Orcs{/link} von {link:hammerfall}Hammerfall{/link} sagen, der schwarze Fleck in der Erde ihres Lagers sei das Blut {link:orgrim-doomhammer}Orgrim{/link} Doomhammers.]=],
		},
	},
})

Translate("deDE", "stromgarde-keep", {
	title = "Burg Stromgarde",
	aliases = { "Stromgarde", "Strom" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Burg Stromgarde ist alles, was von Strom, der ersten Stadt der Menschheit, im Südwesten des Hochlands geblieben ist. Ihre Mauern beherbergen nun drei Heere zugleich. Die {link:boulderfist-ogres}Felsfaustoger{/link} und ihre {link:witherbark-village}Witherbark{/link}-Verbündeten halten einen großen Teil der Stadt und füllen den Turm von {link:arathor}Arathor{/link}, in dem Erzmagier Trelane sich ein letztes Mal zur Wehr setzte, bevor er floh. Das {link:syndicate}Syndikat{/link} hält unter {link:lord-falconcrest}Lord Falconcrest{/link} ein weiteres Viertel. Die letzten Soldaten Stromgardes halten unter {link:prince-galen-trollbane}Prinz Galen Trollbane{/link} den Bezirk um die Kapelle. Hinter der Kapelle liegt das Sanktum, wo {link:thoras-trollbane}König Thoras{/link} in einem versiegelten Grab mit dem Schwert {link:trol-kalar}Trol'kalar{/link} ruht.]=],
		},
		{
			title = "Die Pattsituation",
			text = [=[Keiner der drei kann die anderen vertreiben. Jeder bekämpft seine beiden Rivalen, und die Stadt blutet jeden Tag ein wenig mehr.]=],
		},
	},
})

Translate("deDE", "refuge-pointe", {
	title = "Die Zuflucht",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Zuflucht ist ein befestigtes Lager auf einem Hügel im Herzen des Hochlands. Es beherbergt, was vom Heer Stromgardes nach dem Fall seiner {link:capital-city}Hauptstadt{/link} geblieben ist. {link:captain-nials}Hauptmann Nials{/link} führt hier den Befehl, und ihre Soldaten haben geschworen, das Hochland nicht zu verlassen, bis ihre Stadt wieder ihnen gehört. Vorräte kommen über die Straßen aus {link:southshore}Southshore{/link}, wenn das {link:syndicate}Syndikat{/link} sie durchlässt. In letzter Zeit hat sich das Lager mit neuen Bannern gefüllt: {link:league-of-arathor}Der Bund von Arathor{/link} sammelt sich hier für den Kampf um das {link:arathi-basin}Arathibecken{/link}. Auch zwei Gesandte eines Erzmagiers aus {link:stormwind-city}Stormwind{/link} haben ihre Zelte in der Zuflucht aufgeschlagen.]=],
		},
	},
})

Translate("deDE", "hammerfall", {
	title = "Hammerfall",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Hammerfall liegt auf den östlichen Hügeln des Hochlands. Nach dem {link:second-war}Zweiten Krieg{/link} war es eines der {link:internment-camps}Internierungslager{/link}, in denen die {link:alliance}Allianz{/link} die geschlagenen {link:orcs}Orcs{/link} gefangen hielt. Seine Käfige, Pranger und Galgen stehen noch. {link:thrall}Thrall{/link} und {link:orgrim-doomhammer}Orgrim Doomhammer{/link} kamen, um seine Gefangenen zu befreien, und hier wurde Doomhammer von hinten von der Lanze eines Ritters niedergestreckt. Jahre später kehrten die Orcs zurück und machten die Ruine zu ihrer eigenen. Heute hält {link:drum-fel}Drum Fel{/link} Hammerfall für die {link:horde}Horde{/link}, mit Darkspeartrollen, Entweihten der Verlassenen und einem obersten Heiler der Horde unter seinen Leuten. {link:trolls}Trolle{/link} und {link:ogres}Oger{/link} greifen seine Mauern ohne Unterlass an.]=],
		},
	},
})

Translate("deDE", "go-shek-farm", {
	title = "Go'Sheks Hof",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Go'Sheks Hof liegt im östlichen Tiefland, südwestlich von {link:hammerfall}Hammerfall{/link}. Peons aus Hammerfall bestellen seine Felder unter den Augen orcischer Grunzer, und seine Ernte ernährt den Außenposten. Doch der Hof verbirgt mehr als Korn. In einem kleinen Haus an seinem Südrand führt der Apotheker Jorell der Verlassenen tödliche Experimente durch, und ein Kurier trägt seine Ergebnisse nach Westen zu {link:tarren-mill}Tarrens Mühle{/link}. Zwei Gefährtinnen von {link:phin-odelic}Phin Odelic{/link} beobachten den Hof seit Tagen von den Hügeln aus.]=],
		},
	},
})

Translate("deDE", "circle-of-inner-binding", {
	title = "Kreis der inneren Bindung",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Der Kreis der inneren Bindung ist ein Ring aus aufrechten Steinen auf der Ebene nordöstlich von {link:stromgarde-keep}Stromgarde{/link}. In seiner Mitte steht der Stein der inneren Bindung, der stärkste der vier Steine, die etwas tief unter dem Hochland festhalten. Daneben liegt ein Schlussstein, erfüllt von der Macht der Erde. Geister aus Stein wandeln als Verbannte durch den Kreis und dulden niemanden in ihrer Nähe. Keine Chronik verzeichnet, wer die Steine aufstellte oder wann.]=],
		},
	},
})

Translate("deDE", "circle-of-east-binding", {
	title = "Kreis der östlichen Bindung",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Der Kreis der östlichen Bindung steht auf der Anhöhe nordwestlich von {link:hammerfall}Hammerfall{/link}. Er ist einer von vier Ringen aus aufrechten Steinen, die einen Gefangenen unter dem Hochland gebunden halten. Sein Stein der östlichen Bindung wird von Geistern des Wassers bewacht, den wogenden Verbannten, die sich wie Wellen zwischen den Steinen erheben. Der Stein birgt einen eigenen Schlüssel, und wer den Stein der inneren Bindung öffnen will, muss ihn zuerst dem östlichen Kreis entreißen.]=],
		},
	},
})

Translate("deDE", "circle-of-west-binding", {
	title = "Kreis der westlichen Bindung",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Der Kreis der westlichen Bindung steht im Nordwesten des Hochlands, nicht weit von {link:thoradin-s-wall}Thoradinswall{/link}. Er ist einer der vier Ringe aus aufrechten Steinen, die einen Gefangenen unter der Erde gebunden halten. Geister des Feuers, die brennenden Verbannten, bewachen seinen Stein der westlichen Bindung. Der Schlüssel dieses Steins ist einer der drei, die nötig sind, um den Stein der inneren Bindung zu öffnen. Die Lager des Syndikats beim nahen Northfold haben gelernt, Abstand zu halten.]=],
		},
	},
})

Translate("deDE", "circle-of-outer-binding", {
	title = "Kreis der äußeren Bindung",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Der Kreis der äußeren Bindung steht in der Mitte des Hochlands, auf der Ebene südöstlich der Zuflucht. Er ist einer der vier Ringe aus aufrechten Steinen, die einen Gefangenen unter der Erde binden. Sein Stein der äußeren Bindung wird von Geistern des Windes und des Sturms bewacht, den donnernden Verbannten. Der Stein birgt den dritten der Schlüssel, die den Stein der inneren Bindung öffnen. Reisende auf den Straßen der Zuflucht sehen ihn jeden Tag und wissen wenig von dem, was er verwahrt.]=],
		},
	},
})

Translate("deDE", "northfold-manor", {
	title = "Northfold-Anwesen",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Das Northfold-Anwesen ist ein Gut im Nordwesten des Hochlands, an den Straßen zwischen den Ländereien Stromgardes und {link:hillsbrad-foothills}Hillsbrad{/link}. Das {link:syndicate}Syndikat{/link} hat es zu einem Stützpunkt gemacht. Seine Wegelagerer und Söldner überfallen die Versorgungszüge, die von {link:southshore}Southshore{/link} zur Zuflucht hinaufziehen, und die Soldaten Stromgardes hungern deswegen. Dort geschehen auch schlimmere Dinge. Der Schamane {link:tor-gan}Tor'gan{/link} aus {link:hammerfall}Hammerfall{/link} fand auf dem Gelände Spuren dämonischer Beschwörung und ein Amulett aus Blutstein, das bei dem Werk verbraucht worden war.]=],
		},
	},
})

Translate("deDE", "faldir-s-cove", {
	title = "Die Faldirbucht",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Faldirbucht ist ein kleiner Hafen an der Südküste, unterhalb der Klippen westlich von {link:stromgarde-keep}Stromgarde{/link}. Drei Schiffe der {red:blackwater-raiders}Schwarzmeerräuber{/red} aus {link:booty-bay}Booty Bay{/link} kamen hierher auf der Suche nach einem verlorenen Schatz der Elfen. Nur die {i}Harbinger{/i} von {link:shakes-o-breen}Kapitän O'Breen{/link} erreichte das Ufer. Als die anderen folgten, grollte das Meer, das Wasser wich zurück, und die {i}Spirit of Silverpine{/i} und die {i}Maiden's Folly{/i} zerschellten am Riff. Die {link:naga}Naga{/link} der Daggerspine aus dem versunkenen Riff töteten die meisten Überlebenden. Die gestrandete Mannschaft hält nun ein Lager am Strand.]=],
		},
	},
})

Translate("deDE", "witherbark-village", {
	title = "Witherbark",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Witherbark ist die Heimat der {link:witherbark-trolls}Witherbarktrolle{/link} im Südosten des Hochlands. Ihre Hütten stehen zwischen den Hügeln, und ihre Hexendoktoren, Kopfjäger und Schattenjäger bewahren dort die alten Bräuche ihres Volkes. Hinter dem Dorf öffnen sich die Witherbarkhöhlen, wo sich die Kriegsanführer des Stammes versammeln. Von hier ziehen die {link:trolls}Trolle{/link} aus, um {link:hammerfall}Hammerfall{/link} zu überfallen, und hierher schickte {link:drum-fel}Drum Fel{/link} die ersten seiner Soldaten, um zurückzuschlagen.]=],
		},
	},
})

Translate("deDE", "boulderfist-hall", {
	title = "Halle der Felsfäuste",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Halle der Felsfäuste ist eine Festung der {link:boulderfist-ogres}Felsfaustoger{/link} im Süden des Hochlands, östlich des Thandol-Übergangs. Ihre Höhlen werden von Rohlingen und Ogermagiern gehalten, und angeführt werden sie von {link:kor-gresh-coldrage}Kor'gresh Coldrage{/link}, der seine Sippe mit Eisstößen aus einem gestohlenen Zauberstab in Schach hält. Die {link:ogres}Oger{/link}, die {link:hammerfall}Hammerfall{/link} überfallen, kommen von hier, und die {link:dwarves}Zwerge{/link} am Übergang haben gelernt, ihre Hügel im Auge zu behalten. Auch Molok der Zermalmer soll ihre Hänge durchstreifen.]=],
		},
	},
})

Translate("deDE", "boulder-gor", {
	title = "Fels'gor",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Fels'gor ist ein Ogerhügel auf den Anhöhen nordöstlich von {link:stromgarde-keep}Stromgarde{/link}. Die {link:boulderfist-ogres}Felsfaustoger{/link}, die dort leben, sind weniger und schwächer als die der {link:boulderfist-hall}Halle der Felsfäuste{/link}, doch {link:witherbark-trolls}Witherbarktrolle{/link} teilen ihr Lager, und die beiden Völker ziehen gemeinsam auf Raubzüge. Für die {link:horde}Horde{/link} ist Fels'gor zu einer Prüfung geworden. Tallow aus {link:tarren-mill}Tarrens Mühle{/link} schickt neue Kämpfer zuerst hierher, und nur wer lebend zurückkehrt, wird weiter nach {link:hammerfall}Hammerfall{/link} gesandt. Ein {link:ogres}Oger{/link} namens Kovork streift durch {link:razorfen-downs}die Hügel{/link} rund um den Hügel.]=],
		},
	},
})

Translate("deDE", "dabyrie-s-farmstead", {
	title = "Bauernhof der Dabyries",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Der Bauernhof der Dabyries liegt im Norden des Hochlands, an der Straße östlich der Zuflucht. Er ist die Heimat der Familie Dabyrie: Kenata Dabyrie, Fardel und Marcel. Ihre Arbeiter bestellen noch immer die Felder, und eine eigene Miliz bewacht die Zäune. In einem Land zerstörter Höfe und Banditenlager gehören die Dabyries zu den wenigen {link:humans}Menschen{/link} Stromgardes, die noch wie ihre Väter vom Land leben. Viel mehr ist über sie nicht geschrieben.]=],
		},
	},
})

Translate("deDE", "drywhisker-gorge", {
	title = "Schlucht der Trockenstoppel",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Schlucht der Trockenstoppel schneidet sich im äußersten Nordosten des Hochlands, jenseits von {link:hammerfall}Hammerfall{/link}, in die Berge. Die {link:drywhisker-kobolds}Trockenstoppelkobolde{/link} haben sie mit ihren Tunneln, ihren Vermessern und ihren Gräbern gefüllt, und ein Koboldgeomant namens Flintdagger wirkt unter ihnen Feuer. Tief in der Schlucht steht eine Gruppe glitzernder Kristallsplitter. Die {link:kobolds}Kobolde{/link} bewachen sie, und sie tragen Partikel einer seltsamen Macht bei sich. Die Stimme unter dem Hochland nennt sie Verbündete ihrer Kerkermeister.]=],
		},
	},
})

Translate("deDE", "arathi-basin", {
	title = "Arathibecken",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Das Arathibecken ist ein von Bergen umringtes Tal im Herzen des Hochlands, eines der fruchtbarsten Länder der {link:eastern-kingdoms}Östlichen Königreiche{/link}. Sein Hof, seine Mine, sein Sägewerk, seine Schmiede und seine Ställe wurden gebaut, um ein Königreich zu ernähren. Nun kämpfen zwei Heere darum. {link:league-of-arathor}Der Bund von Arathor{/link} hält Trollbanes Halle und will die Reichtümer des Beckens für {link:stormwind-city}Stormwind{/link} und die {link:alliance}Allianz{/link} gewinnen. {link:defilers}Die Entweihten{/link} der Verlassenen halten die entweihte Feste und wollen die {link:humans}Menschen{/link} von ihren zwergischen Verbündeten im Süden abschneiden. Ihre Straßen führen von der Zuflucht und von {link:hammerfall}Hammerfall{/link} herab.]=],
		},
	},
})

Translate("deDE", "captain-nials", {
	title = "Hauptmann Nials",
	subtitle = "Befehlshaberin der Zuflucht",
	found = "Die Zuflucht",
	hint = "Sprecht mit der Befehlshaberin des Lagers in der Zuflucht.",
	allegiance = "Königreich Stromgarde · Allianz",
	aliases = { "Nials" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Hauptmann Nials befehligt die Soldaten Stromgardes in der Zuflucht. Sie hat keine Stadt zu verteidigen, nur die Hoffnung, eine zurückzugewinnen. Ihr Heer schwindet, während ihre Feinde wachsen, und jede Woche kämpfen die {link:ogres}Oger{/link}, das {link:syndicate}Syndikat{/link} und ihre eigene Miliz in den Ruinen der {link:capital-city}Hauptstadt{/link} einen blutigeren Stillstand aus.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Nials ist die Stimme eines Königreichs, das sich weigert zu sterben. Als die {link:dwarves}Zwerge{/link} vom {link:thandol-span}Thandol-Übergang{/link} sie um Soldaten anflehten, lehnte sie voller Kummer ab. Die Ehre, sagte sie, halte ihr Heer im Hochland, bis das Banner des Königs wieder über {link:stromgarde-keep}Stromgarde{/link} wehe.]=],
		},
		{
			title = "Taten",
			text = [=[• Sie schickt Kämpfer gegen das {link:syndicate}Syndikat{/link} am {link:northfold-manor}Northfold-Anwesen{/link}, um die Versorgungsstraßen aus {link:southshore}Southshore{/link} offen zu halten.
• Sie zahlt für die Abzeichen gefallener Milizsoldaten, die dem Syndikat wieder abgenommen werden, damit die Familien der Toten ihr Schicksal erfahren.
• Sie hat Kopfgelder auf die Hexenmeisterin {link:marez-cowl}Marez Cowl{/link} des Syndikats, auf {link:lord-falconcrest}Lord Falconcrest{/link} und auf seinen Leibwächter Otto ausgesetzt.]=],
		},
		{
			title = "Nicht überliefert",
			text = [=[Die Aufzeichnungen der Zuflucht nennen nur ihren Rang und ihre Taten. Über ihr Leben vor dem Fall der Stadt ist nichts geschrieben.]=],
		},
	},
	chapters = {
		{
			title = "Die Bitte vom Übergang",
			hint = [=[Bringt die Bitte der Zwerge aus dem Sumpfland in die Zuflucht.]=],
			text = [=[Die {link:dwarves}Zwerge{/link} von {link:dun-modr}Dun Modr{/link} hatten ihre Stadt und die Hälfte ihrer Brücke verloren, und sie baten die Zuflucht um Hilfe. Nials hörte die Nachricht vom {link:thandol-span}Thandol-Übergang{/link} schweren Herzens. Doch sie hatte nichts zu geben. {link:stromgarde-keep}Stromgarde{/link} war gefallen, und jedes Schwert, das sie besaß, wurde gebraucht, um es zurückzuerobern. Sie ließ ausrichten, dass die Zwerge allein standhalten müssten.]=],
		},
		{
			title = "Die Abzeichen der Gefallenen",
			hint = "Holt zurück, was das Syndikat den Toten Stromgardes nimmt.",
			text = [=[Das {link:syndicate}Syndikat{/link} bezahlt sein Gesindel mit Gold für jedes Abzeichen Stromgardes, das einem toten Milizsoldaten abgeschnitten wird. Nials wollte nicht zulassen, dass die Banditen an ihren Toten verdienten. Als die Abzeichen zurückkamen, hängte sie sie nicht als Trophäen auf. Sie schickte jeder Familie Nachricht, dass ihr Soldat im Kampf gefallen war, denn sie hielt eine grimmige Nachricht für gnädiger als Schweigen.]=],
		},
	},
	mentions = {
		{
			text = [=[Eine Bitte an die {link:alliance}Allianz{/link}, das Gesuch der {link:dwarves}Zwerge{/link}]=],
		},
		{ text = "{link:northfold-manor}Northfold-Anwesen{/link}" },
		{ text = "Abzeichen von {link:stromgarde-keep}Stromgarde{/link}" },
		{ text = "Gesucht! {link:marez-cowl}Marez Cowl{/link}" },
		{ text = "Gesucht! Otto und {link:lord-falconcrest}Falconcrest{/link}" },
	},
	bonds = {
		{ id = "rhag-garmason", name = "Rhag Garmason", note = "bat sie um Soldaten" },
		{ id = "longbraid-the-grim", name = "Longbraid der Grimmige", note = "der Zwerg, dem sie nicht helfen konnte" },
		{ id = "lord-falconcrest", name = "Lord Falconcrest", note = "ein Feind mit einem Kopfgeld auf seinem Haupt" },
		{ id = "marez-cowl", name = "Marez Cowl", note = "eine Feindin mit einem Kopfgeld auf ihrem Haupt" },
		{ id = "prince-galen-trollbane", name = "Prinz Galen Trollbane", note = "ihr Prinz in den Ruinen" },
	},
})

Translate("deDE", "sergeant-maclear", {
