		},
	},
	bonds = {
		{ id = "field-marshal-oslight", name = "Feldmarschall Oslight", note = "sein Befehlshaber" },
		{ id = "captain-nials", name = "Hauptmann Nials", note = "führt das ältere Lager" },
	},
})

