	},
})

Translate("deDE", "apprentice-kryten", {
	title = "Lehrling Kryten",
	subtitle = "Gesandter von Erzmagier Malin",
	found = "Die Zuflucht",
	hint = "Sucht den jungen Lehrling aus Stormwind in der Zuflucht.",
	allegiance = "Erzmagier Malin von Stormwind",
	aliases = { "Kryten" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Kryten ist ein Lehrling von Erzmagier Malin aus {link:stormwind-city}Stormwind{/link}. Sein Meister schickte ihn mit dem {link:dwarves}Zwerg{/link} {link:skuerto}Skuerto{/link} ins Hochland, um Reagenzien zu sammeln und zu bergen, was Erzmagier Trelane beim Fall Stromgardes verlor. Er ist geschickt mit Zaubern und in der Wildnis weit weniger zu Hause.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Kryten und {link:skuerto}Skuerto{/link} sind die einzigen Diener der Magier Stormwinds, die im Hochland am Werk sind, und ihr Auftrag führt geradewegs in den von Ogern besetzten Turm von {link:arathor}Arathor{/link}.]=],
		},
		{
			title = "Taten",
			text = [=[• Er bittet um die Hauer, Medizinbeutel und Messer der {link:witherbark-trolls}Witherbarktrolle{/link}.
• Er verzaubert einen azurblauen Achat, damit er die alten Verteidigungen des Turms von {link:arathor}Arathor{/link} erweckt.
• Er warnt Neuankömmlinge, Skuertos Späharbeit niemals zu kritisieren.]=],
		},
	},
	mentions = {
