		{ id = "kor-gresh-coldrage", name = "Kor'gresh Coldrage", note = "hat Trelanes Zauberstab" },
		{ id = "archmage-malin", name = "Erzmagier Malin", note = "sein Dienstherr" },
	},
})

Translate("deDE", "prince-galen-trollbane", {
	title = "Prinz Galen Trollbane",
	subtitle = "Erbe von Stromgarde",
	found = "Die Kapelle im Viertel der Verteidiger von Burg Stromgarde",
	hint = "Sucht den Prinzen, der das letzte Viertel Stromgardes hält.",
	allegiance = "Königreich Stromgarde",
	aliases = { "Galen Trollbane", "Galen" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Prinz Galen Trollbane ist der Sohn von {link:thoras-trollbane}König Thoras{/link} und der Erbe eines gefallenen Throns. Er hält den letzten Winkel Stromgardes, der noch ihm gehört, einen Bezirk der alten Stadt rund um ihre Kapelle. Hinter dieser Kapelle liegt sein Vater begraben. Galen bewacht das Grab, und er bewacht das Schwert, das darin liegt.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Galen ist der Letzte der Trollbanes im Hochland, aus der Linie des Ignaeus, der das Schwert {link:trol-kalar}Trol'kalar{/link} gegen die {link:trolls}Trolle{/link} errang. Für die Trolle der {link:horde}Horde{/link} ist sein Blut ein uralter Feind. Für seine Soldaten ist er alles, was von ihrem König geblieben ist.]=],
		},
		{
			title = "Taten",
			text = [=[• Er versiegelte das Grab seines Vaters mit Siegeln und verteilte sie unter den Überlebenden Stromgardes.
• Er zerbrach das Siegel von {link:thoradin}Thoradin{/link} in Stücke und gab sie seinen Verteidigern zu tragen.
• Er gab das Siegel von {link:arathor}Arathor{/link} {link:lieutenant-valorcall}Leutnant Valorcall{/link} und behält das Siegel von Trollbane selbst.
• Er schickt den Rest seiner Reiterei quer durch das Hochland.]=],
		},
		{
			title = "Nicht überliefert",
			text = [=[Keine Chronik dieser Tage verzeichnet, wie {link:thoras-trollbane}König Thoras{/link} starb oder wie sein Sohn an seiner Stelle zur Herrschaft kam.]=],
		},
	},
	chapters = {
		{
			title = "Das geteilte Siegel",
			hint = [=[Erfahrt, wie der Prinz von Stromgarde das Grab seines Vaters schützt.]=],
			text = [=[Das Grab von {link:thoras-trollbane}König Thoras{/link} lässt sich nicht mit Gewalt öffnen. Galen band es mit Siegeln, und er verstreute sie, damit kein einzelner Verlust sie alle kosten konnte. Eines fiel dem {link:syndicate}Syndikat{/link} zu, als {link:stromgarde-keep}Stromgarde{/link} fiel. Das Siegel von {link:thoradin}Thoradin{/link} zerbrach er in viele Stücke und teilte sie unter seinen Verteidigern auf, damit man es aus vielen Händen nehmen müsste.]=],
		},
		{
			title = "Die Kapelle",
			hint = [=[Sucht den Prinzen in der Kapelle des Viertels der Verteidiger auf.]=],
			text = [=[Das letzte Siegel hing an der Seite des Prinzen selbst, tief in der Kapelle des Viertels der Miliz. Er war gut bewacht und selbst kein schwacher Kämpfer. Als der {link:darkspear-trolls}Darkspear{/link}-Jäger {link:zengu}Zengu{/link} das Siegel endlich in Händen hielt, stellte er nur eine Frage: ob die Linie des Ignaeus Trollbane gebrochen sei.]=],
		},
	},
	mentions = {
		{ text = "Das zerbrochene Siegel" },
		{ text = "Siegel von {link:arathor}Arathor{/link}" },
		{ text = "Siegel von Trollbane" },
	},
	bonds = {
		{ id = "thoras-trollbane", name = "Thoras Trollbane", note = "sein Vater" },
		{ id = "lieutenant-valorcall", name = "Leutnant Valorcall", note = "sein Anführer der Reiterei" },
		{ id = "zengu", name = "Zengu", note = "sucht sein Siegel" },
		{ id = "trol-kalar", name = "Trol'kalar", note = "das Schwert seines Hauses" },
	},
})

