	allegiance = "Syndikat",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Marez Cowl ist eine hohe Beraterin und Agentin des {link:syndicate}Syndikats{/link} und eine Hexenmeisterin von wahrer Macht. In den Ruinen Stromgardes ruft sie Dämonen herbei, die sie gegen die Verteidiger der Stadt schickt, und schöpft dabei aus einer Kugel aus Blutstein. In der Zuflucht flüstert man, sie trage Botschaften zwischen dem Syndikat und einer dunkleren Macht hin und her.]=],
