		{ text = "Üble Magie, ihre Kugel" },
	},
	bonds = {
		{ id = "tor-gan", name = "Tor'gan", note = "sucht ihre Kugel" },
		{ id = "captain-nials", name = "Hauptmann Nials", note = "hat das Kopfgeld auf sie ausgesetzt" },
		{ id = "lord-falconcrest", name = "Lord Falconcrest", note = "ihr Herr im Hochland" },
	},
})

