Translate("deDE", "or-kalar", {
	title = "Or'Kalar",
	subtitle = "Oger des Turms von Arathor",
	found = "Nahe dem Turm von Arathor in Burg Stromgarde",
	hint = "Stellt Euch dem Oger, der nahe dem Turm von Arathor wartet.",
	allegiance = "Felsfaustoger · Mug'thol",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Or'Kalar ist ein {link:ogres}Oger{/link}, der die {link:boulderfist-ogres}Felsfäuste{/link} in den Ruinen nahe dem Turm von {link:arathor}Arathor{/link} anführt. Er dient einem größeren Oger, {link:mug-thol}Mug'thol{/link}, der ihn aus der Ferne befehligt. Or'Kalar wurde vor Jahren von {link:drum-fel}Drum Fel{/link} aus {link:hammerfall}Hammerfall{/link} besiegt, und er hat es nie vergessen. Die Angriffe auf Hammerfall sind sein Werk.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Or'Kalars Hass ist die verborgene Ursache der langen Belagerung Hammerfalls. Er stellte {link:drum-fel}Drum Fel{/link} eine Falle, und nur Korin Fels Voraussicht bewahrte ihren Gatten davor, hineinzulaufen.]=],
		},
		{
			title = "Taten",
