Translate("deDE", "drum-fel", {
	title = "Drum Fel",
	subtitle = "Befehlshaber von Hammerfall",
	found = "Hammerfall",
	hint = [=[Sprecht mit dem Orc, der die Verteidigung von Hammerfall anführt.]=],
	allegiance = "Horde · Hammerfall",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Drum Fel führt die Krieger von {link:hammerfall}Hammerfall{/link} an. Er hat keine Zeit, seine eigene Axt zu schärfen, denn {link:trolls}Trolle{/link} und {link:ogres}Oger{/link} greifen Tag für Tag seine Mauern an. Für Unerprobte hat er wenig Geduld, doch er nimmt jeden Kämpfer, der sich als stark genug erweist, und an Kämpfen, die er ihnen geben kann, fehlt es nie.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Drum Fel ist der Wille, der {link:hammerfall}Hammerfall{/link} zusammenhält. Er will den Völkern des Hochlands zeigen, dass auch die {link:orcs}Orcs{/link} hier eine Heimat haben und dass sie sich nicht daraus vertreiben lassen.]=],
		},
		{
			title = "Taten",
			text = [=[• Er schickt seine Kämpfer gegen die {link:witherbark-trolls}Witherbarktrolle{/link} im Süden, die den {link:orcs}Orcs{/link} den Rücken kehrten.
• Er schickt sie gegen die Schläger und Magier der {link:boulderfist-ogres}Felsfäuste{/link} in der {link:boulderfist-hall}Halle der Felsfäuste{/link}.
• Er schlägt gegen die Lords und Schamanen der Felsfäuste in den Ruinen Stromgardes zu.
• Vor Jahren besiegte er den {link:ogres}Oger{/link} {link:or-kalar}Or'Kalar{/link}.]=],
		},
		{
			title = "Nicht überliefert",
			text = [=[Die Aufzeichnungen Hammerfalls sagen nicht, wo Drum Fel kämpfte, bevor er hierherkam, oder wann er {link:or-kalar}Or'Kalar{/link} zum ersten Mal begegnete.]=],
		},
	},
	chapters = {
		{
			title = "Eine Heimat im Hochland",
			hint = [=[Schließt Euch dem Kampf an, Hammerfall gegen die Trolle zu verteidigen.]=],
			text = [=[Die {link:witherbark-village}Witherbark{/link} und die {link:boulderfist-ogres}Felsfäuste{/link} hatten gemeinsame Sache gemacht, um das Hochland von den {link:orcs}Orcs{/link} zu befreien. Drum Fel kannte die {link:trolls}Trolle{/link} aus alten Tagen: Einst hatten sie an der Seite der {link:horde}Horde{/link} gekämpft, und dann hatten sie sie verlassen. Er gedachte nicht, ihnen {link:hammerfall}Hammerfall{/link} zu überlassen. Sein erster Schlag traf ihre Lager im Süden.]=],
		},
		{
			title = "Der Kopf der Bestie",
			hint = "Tragt den Krieg zu den Ogerlords in den Ruinen Stromgardes.",
			text = [=[Die Anführer der Angriffe hatten ihren Unterschlupf in {link:stromgarde-keep}Stromgarde{/link} eingerichtet, das Drum Fel ein Denkmal menschlicher Schwäche nannte. Als seine Kämpfer aus den Ruinen zurückkehrten, ließ der Druck auf {link:hammerfall}Hammerfall{/link} endlich nach. Er begann zu glauben, dass sein Volk im Hochland gedeihen könnte.]=],
		},
	},
	mentions = {
		{ text = "Der Hammer könnte fallen, gesandt von Tallow" },
		{ text = "Zu den Waffen" },
		{ text = "Zu den Waffen" },
		{ text = "Zu den Waffen" },
	},
	bonds = {
		{ id = "korin-fel", name = "Korin Fel", note = "seine Gattin" },
		{ id = "or-kalar", name = "Or'Kalar", note = "ein alter Feind" },
		{ id = "gor-mul", name = "Gor'mul", note = "ein Überlebender des Lagers" },
	},
})

