	found = "Hammerfall",
	hint = "Sprecht mit der Gattin des Befehlshabers von Hammerfall.",
	allegiance = "Horde · Hammerfall",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Korin Fel ist die Gattin von {link:drum-fel}Drum Fel{/link} und eine Deuterin von Vorzeichen. Ihre Weissagungen verrieten ihr, was ihr Gatte nicht weiß: dass die Angriffe auf {link:hammerfall}Hammerfall{/link} vom {link:ogres}Oger{/link} {link:or-kalar}Or'Kalar{/link} ausgehen und dass er Drum eine Falle gestellt hat.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Korin wählte das Schweigen, um das Leben ihres Gatten zu retten. Sie verbarg die Zeichen Or'Kalars vor ihm, wohl wissend, dass er kopfüber in die Falle stürmen würde. Sie verlangt nicht, dafür für ehrenhaft gehalten zu werden, nur verstanden zu werden.]=],
		},
		{
			title = "Taten",
			text = [=[• Sie liest die Zukunft in Weissagungen.
• Sie verbirgt Or'Kalars Spur vor {link:drum-fel}Drum Fel{/link}.]=],
		},
	},
	chapters = {
		{
			title = "Die wahre Bedrohung",
			hint = [=[Erfahrt das Geheimnis, das die Gattin des Befehlshabers von Hammerfall hütet.]=],
			text = [=[Als {link:or-kalar}Or'Kalar{/link} nahe dem Turm von {link:arathor}Arathor{/link} fiel, endeten die Angriffe auf {link:hammerfall}Hammerfall{/link} für eine Weile. {link:drum-fel}Drum Fel{/link} erfuhr nie, wie nah er dem Verderben gewesen war. Korin erzählte es nur demjenigen, der die Tat vollbracht hatte.]=],
		},
	},
	mentions = {
		{ text = "Die wahre Bedrohung" },
	},
	bonds = {
		{ id = "drum-fel", name = "Drum Fel", note = "ihr Gatte" },
		{ id = "or-kalar", name = "Or'Kalar", note = "der Feind, den sie verbarg" },
	},
})

Translate("deDE", "gor-mul", {
	title = "Gor'mul",
	subtitle = "Überlebender des Lagers",
	found = "Hammerfall",
	hint = [=[Sprecht mit dem alten Orc von Hammerfall, der sich an das Lager erinnert.]=],
	allegiance = "Horde · Hammerfall",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Gor'mul war ein Gefangener in dem Lager, das heute {link:hammerfall}Hammerfall{/link} ist. Er war an dem Tag dort, als {link:thrall}Thrall{/link} und Doomhammer kamen, um es zu befreien, und er sah, wie die Lanze eines Ritters den Kriegshäuptling von hinten traf. Im Chaos entkamen die anderen {link:orcs}Orcs{/link}. Gor'mul blieb zurück und wanderte jahrelang allein durch das Hochland.]=],
