			title = "Bedeutung",
			text = [=[Gor'mul trägt die Trauer der alten {link:horde}Horde{/link}. Er wünscht, er wäre an Doomhammers Seite gestorben, und zunächst konnte ihn keine Erzählung von {link:orgrimmar}Orgrimmar{/link} oder vom neuen Kriegshäuptling bewegen.]=],
		},
		{
			title = "Taten",
			text = [=[• Er wurde Zeuge des Todes von {link:orgrim-doomhammer}Orgrim Doomhammer{/link}.
• Er erzählt jedem Neuankömmling, wie {link:hammerfall}Hammerfall{/link} verloren und zurückgewonnen wurde.]=],
		},
	},
	chapters = {
		{
			title = "Die List des Raptors",
			hint = [=[Helft dem Schamanen von Hammerfall, den trauernden Krieger zu erreichen.]=],
			text = [=[Gor'mul warf das erste Amulett in den Staub. Das zweite Geschenk war eine Kugel, die den Geist des Raptors in ihn strömen ließ, und zum ersten Mal spürte der alte Krieger die neue Macht der Schamanen. Für den Augenblick, sagte er, werde er zuhören.]=],
		},
	},
	mentions = {
		{ text = "{link:hammerfall}Hammerfall{/link}" },
		{ text = "Geister erwecken" },
		{ text = "List des Raptors" },
		{ text = "List des Raptors" },
	},
	bonds = {
		{ id = "tor-gan", name = "Tor'gan", note = "wollte ihn nicht aufgeben" },
		{ id = "drum-fel", name = "Drum Fel", note = "sein Befehlshaber" },
		{ id = "orgrim-doomhammer", name = "Orgrim Doomhammer", note = "der Kriegshäuptling, den er fallen sah" },
	},
})

Translate("deDE", "tor-gan", {
	title = "Tor'gan",
	subtitle = "Schamane von Hammerfall",
	found = "Hammerfall",
	hint = "Sprecht mit dem Trollschamanen von Hammerfall.",
	allegiance = "Horde · Darkspear",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Tor'gan ist ein Trollschamane von {link:hammerfall}Hammerfall{/link}. Er ist geduldig, wo {link:drum-fel}Drum Fel{/link} ungestüm ist, und er glaubt, dass die neuen schamanischen Kräfte der {link:horde}Horde{/link} Wunden heilen können, die Schwerter nicht heilen. Er spürt auch dunklere Magie. Wenn irgendwo im Hochland Dämonen gerufen werden, fühlt er es in seinem Blut brennen.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Tor'gan ist der Heiler von Hammerfalls Geist. Er wollte den gebrochenen Krieger {link:gor-mul}Gor'mul{/link} nicht aufgeben, und er wollte die dämonische Magie nicht übersehen, die sich im {link:syndicate}Syndikat{/link} ausbreitet.]=],
		},
		{
			title = "Taten",
			text = [=[• Er fand die Spuren dämonischer Beschwörung am {link:northfold-manor}Northfold-Anwesen{/link} und ein verbrauchtes Amulett aus Blutstein.
• Er sucht die Kugel der Hexenmeisterin, die in {link:stromgarde-keep}Stromgarde{/link} Dämonen ruft, um sie zu zerstören.
• Er fertigte Amulette und eine Kugel aus den Augen und Herzen von Raptoren, um Gor'muls Geist zu wecken.
• Er fügte die zerbrochenen Stücke des Siegels von {link:thoradin}Thoradin{/link} wieder zu einem zusammen.]=],
		},
	},
	chapters = {
		{
			title = "Üble Magie",
			hint = [=[Findet die Quelle der Dämonenmagie, die den Schamanen beunruhigt.]=],
			text = [=[Eine mächtige Hexenmeisterin hauste in {link:stromgarde-keep}Stromgarde{/link}, und von Zeit zu Zeit rief ein Relikt in ihren Händen Dämonen in großer Zahl herbei. Als die Kugel aus Blutstein zu Tor'gan kam, versprach er, sie zu zerstören. Sie erinnere ihn, sagte er, an die Macht, die die Dämonen einst über die {link:orcs}Orcs{/link} hatten, bevor Hellscream ihren Fluch brach.]=],
		},
		{
			title = "Ein erwachter Krieger",
			hint = "Helft dem Schamanen, Gor'muls Geist wiederherzustellen.",
			text = [=[Tor'gans erstes Amulett versagte. Er ließ sich nicht entmutigen. Er sammelte die Herzen von Raptoren und band ihren Geist in eine Kugel, und endlich spürte {link:gor-mul}Gor'mul{/link}, was der Schamane vermochte. Tor'gan wartete, bis die Verzauberung verblasste, und dann ging er, um mit ihm zu sprechen.]=],
		},
		{
			title = "Das wiederhergestellte Siegel",
			hint = [=[Bringt das zerbrochene Siegel Stromgardes zum Trollschamanen.]=],
			text = [=[Die Bruchstücke des Siegels von {link:thoradin}Thoradin{/link} kamen von den Leichen der Verteidiger Stromgardes zu Tor'gan. Die Magie, die es gehalten hatte, war noch da. Mit einem Lichtblitz machte er es wieder ganz und schickte es zu {link:zengu}Zengu{/link} zurück.]=],
		},
	},
	mentions = {
		{ text = "Üble Magie" },
		{ text = "Üble Magie" },
		{ text = "Geister erwecken" },
		{ text = "List des Raptors" },
		{ text = "Das zerbrochene Siegel" },
		{ text = "Siegel von {link:thoradin}Thoradin{/link}" },
	},
	bonds = {
		{ id = "gor-mul", name = "Gor'mul", note = "der Krieger, den er heilte" },
		{ id = "zengu", name = "Zengu", note = "sein Verbündeter bei der Jagd nach dem Schwert" },
		{ id = "marez-cowl", name = "Marez Cowl", note = "die Hexenmeisterin, die er jagt" },
	},
})

Translate("deDE", "zengu", {
	title = "Zengu",
	subtitle = "Jäger der Darkspear",
	found = "Hammerfall",
	hint = [=[Sprecht mit dem Darkspear-Jäger, der mit einem Auftrag nach Hammerfall gekommen ist.]=],
	allegiance = "Darkspear · Horde",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Zengu ist ein erfahrener Jäger der {link:darkspear-trolls}Darkspear{/link}. {link:vol-jin}Vol'jin{/link} schickte ihn mit einer einzigen Aufgabe nach {link:hammerfall}Hammerfall{/link}: das Schwert {link:trol-kalar}Trol'kalar{/link} aus dem Grab der Trollbanes zu holen. Die Darkspear wollen es in ihren Krieg gegen die {link:trolls}Trolle{/link} von {link:zul-gurub}Zul'Gurub{/link} tragen.]=],
		},
		{
			title = "Bedeutung",
			text = [=[In Zengus Jagd schließt sich der Kreis des ältesten Krieges des Hochlands. Die Klinge, die die Herren von {link:stromgarde-keep}Strom{/link} einst gegen die {link:trolls}Trolle{/link} führten, wird von Trollen gesucht, um sie gegen andere Trolle zu führen.]=],
		},
		{
			title = "Taten",
			text = [=[• Er verfolgt die vier Siegel, die das Grab von {link:thoras-trollbane}König Thoras{/link} verschließen.
• Er nimmt das erste Siegel dem {link:syndicate}Syndikat{/link} in {link:stromgarde-keep}Stromgarde{/link} ab.
• Er jagt den Anführer der Reiterei {link:lieutenant-valorcall}Valorcall{/link} wegen des Siegels von {link:arathor}Arathor{/link}.
• Er sucht das letzte Siegel bei Prinz {link:prince-galen-trollbane}Galen{/link} selbst.]=],
		},
	},
	chapters = {
		{
			title = "Das Siegel von Strom",
			hint = [=[Sucht das erste der Siegel, die das Grab der Trollbanes schützen.]=],
			text = [=[Zengu kennt die alte Geschichte. Als die {link:trolls}Trolle{/link} gegen das Reich {link:arathor}Arathor{/link} kämpften, war ihr größter Feind Lord Ignaeus von {link:stromgarde-keep}Strom{/link}, genannt Trollbane, der mit der Klinge {link:trol-kalar}Trol'kalar{/link}, dem Trolltöter, in den Krieg ritt. Nun waren die Söhne Trollbanes schwach, und ihre Festung lag in Trümmern. Das {link:syndicate}Syndikat{/link} hielt das erste Siegel. Dort begann Zengu.]=],
		},
		{
			title = "Das befreite Schwert",
			hint = "Öffnet das Grab der Trollbanes.",
			text = [=[Die vier Siegel fügten sich zu einem zusammen, dem Siegel des Ignaeus. Seine Linien passten zu den Schnitzereien auf dem Grab im Sanktum, und die Hände aus Stein gaben ihr Schwert frei. Über Generationen, sagte Zengu, hätten {link:stromgarde-keep}Strom{/link} und {link:arathor}Arathor{/link} die {link:trolls}Trolle{/link} heimgesucht. Nun gehöre ihre größte Waffe den {link:darkspear-trolls}Darkspear{/link}, und er werde dafür sorgen, dass sie zu {link:nimboya}Nimboya{/link} nach {link:grom-gol-base-camp}Grom'gol{/link} gebracht werde.]=],
		},
	},
	mentions = {
		{ text = "Trollbane, gesandt von {link:nimboya}Nimboya{/link}" },
		{ text = "Siegel von {link:stromgarde-keep}Strom{/link}" },
		{ text = "Das zerbrochene Siegel" },
		{ text = "Siegel von {link:arathor}Arathor{/link}" },
		{ text = "Siegel von Trollbane" },
		{ text = "{link:trol-kalar}Trol'kalar{/link}" },
		{ text = "{link:trol-kalar}Trol'kalar{/link}" },
	},
	bonds = {
		{ id = "vol-jin", name = "Vol'jin", note = "schickte ihn" },
		{ id = "tor-gan", name = "Tor'gan", note = "stellte das zerbrochene Siegel wieder her" },
		{ id = "prince-galen-trollbane", name = "Prinz Galen Trollbane", note = "hütet das letzte Siegel" },
		{ id = "trol-kalar", name = "Trol'kalar", note = "das Schwert, das er sucht" },
	},
})

