Translate("deDE", "myzrael", {
	title = "Myzrael",
	subtitle = "Die Prinzessin der Erde",
	found = [=[Unter dem Arathihochland; sie spricht durch die Splitter von Myzrael]=],
	hint = [=[Lauscht auf die Stimme, die durch einen Kristall in den nördlichen Bergen fleht.]=],
	allegiance = "Sie selbst · ihr dient der Schattenhammer",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Myzrael ist ein Wesen der tiefen Erde, das gebunden unter dem {link:arathi-highlands}Arathihochland{/link} liegt. Sie nennt sich eine Prinzessin der Erde. Die Riesen legten sie dort in Ketten, und vier Steine der Bindung halten sie fest. Nur durch Kristallsplitter kann sie zur Welt oben sprechen, und sie spricht süß und fleht um Rettung.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Myzrael ist das Geheimnis des Hochlands. Der {link:twilight-s-hammer}Schattenhammer{/link} nennt sie die Herrin und arbeitet auf ihre Rückkehr hin. Derjenige, der mit ihrer Schriftrolle aus dem Orden floh, glaubt, dass die Riesen sie aus gutem Grund banden und dass man ihr niemals erlauben darf, stark zu werden.]=],
		},
		{
			title = "Taten",
			text = [=[• Sie ruft Reisende in Visionen durch einen Splitter ihres Kristalls.
• Sie schickt sie aus, die Splitter zu erwecken, die die {link:drywhisker-kobolds}Trockenstoppelkobolde{/link} hüten.
• Sie verlangt die drei Schlüssel der Steine der Bindung und den Stab der Ordnung vom Steinwächter {link:fozruk}Fozruk{/link}.
• Sie nennt Verbündete in {link:ironforge}Ironforge{/link} und in {link:hammerfall}Hammerfall{/link}.]=],
		},
		{
			title = "Nicht überliefert",
			text = [=[Keine Chronik Azeroths spricht von Myzrael. Was sie ist, woher sie kam und warum die Riesen sie banden, ist nur aus ihren eigenen Worten und denen Theldurins des Verlorenen bekannt.]=],
		},
	},
	chapters = {
		{
			title = "Die Stimme im Kristall",
			hint = [=[Folgt dem Flehen, das aus einem Kristall in den nördlichen Bergen kommt.]=],
			text = [=[Ein Splitter pulsierte in der Hand, und eine Vision zeigte einen Kristall in den nördlichen Bergen. Dort nannte die Stimme ihren Namen: Myzrael, von Riesen tief unten gefangen. Sie bat um Hilfe, und sie bat sanft darum.]=],
		},
		{
			title = "Frei",
			hint = "Öffnet den Schlussstein am Kreis der inneren Bindung.",
			text = [=[Als der Stab der Ordnung sich im Schlussstein drehte, bebte die Erde. Myzrael rief, sie sei frei. Sie wollte ihren Kerkermeistern noch nicht gegenübertreten. Sie würde sich verbergen, stark werden und die Riesen eines Tages für ihre Wacht bezahlen lassen. Wenn sie bereit wäre, müsste man sie beschwören.]=],
		},
		{
			title = "Die Fesseln",
			hint = "Erfahrt, was der wahnsinnige Hüter der Schriftrolle weiß.",
			text = [=[{link:theldurin-the-lost}Theldurin der Verlorene{/link} hatte die Schriftrolle Myzraels gestohlen und sie gelesen. Man müsse sie beschwören und besiegen, bevor sie ihre Macht sammle, sagte er, und sie mit ihren eigenen unheimlichen Fesseln erneut binden. Als sich die Fesseln um die Splitter schlossen, stieg ein Schrei aus der Tiefe auf, und dann ein Brüllen. Die Splitter hatten sich einst warm angefühlt. Nun drohten sie nur noch.]=],
		},
	},
	mentions = {
		{ text = "Kristall in den Bergen" },
		{ text = "Die gefangene Prinzessin" },
		{ text = "Steine der Bindung" },
		{ text = "Den Schlussstein brechen" },
		{ text = "Myzraels Verbündete" },
		{ text = "Myzraels Verbündete" },
		{ text = "{link:theldurin-the-lost}Theldurin der Verlorene{/link}" },
		{ text = "Die Beschwörung der Prinzessin" },
	},
	bonds = {
		{ id = "zaruk", name = "Zaruk", note = "dient ihr in Hammerfall" },
		{ id = "gerrig-bonegrip", name = "Gerrig Bonegrip", note = "dient ihr in Ironforge" },
		{ id = "fozruk", name = "Fozruk", note = "einer ihrer Kerkermeister" },
		{ id = "theldurin-the-lost", name = "Theldurin der Verlorene", note = "floh mit ihrer Schriftrolle" },
	},
})

Translate("deDE", "thoradin", {
	title = "Thoradin",
	subtitle = "Erster König von Arathor",
	allegiance = "Der Stamm der Arathi · Arathor",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Thoradin war der Kriegsherr des Stammes der {link:arathi-highlands}Arathi{/link}, der die Menschheit zu einer Nation machte. In einem Zeitalter, in dem die Menschenstämme des Nordens einander bekämpften, während die {link:trolls}Trolle{/link} sie alle jagten, vereinte er sie unter einem Banner. Er nannte das neue Reich {link:arathor}Arathor{/link} und errichtete seine {link:capital-city}Hauptstadt{/link} {link:stromgarde-keep}Strom{/link} in dem Hochland, das den Namen seines Stammes trägt. Jedes Menschenreich der Gegenwart geht auf sein Werk zurück.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Vor Thoradin gab es Stämme. Nach ihm gab es ein Volk. Sein Bündnis mit den Elfen gewann die {link:troll-wars}Trollkriege{/link} und brachte der Menschheit das Wissen der Magie, und seine Blutlinie wurde von den Elfen von {link:quel-thalas}Quel'Thalas{/link} Tausende Jahre lang geehrt. Die große Mauer zwischen dem Hochland und {link:hillsbrad-foothills}Hillsbrad{/link} trägt noch immer seinen Namen.]=],
		},
		{
			title = "Die Einigung der Stämme",
			text = [=[Die {link:arathi-highlands}Arathi{/link} hatten länger gegen die Amani gekämpft als jeder andere Stamm, und Thoradin hatte den Krieg an der Grenze zu den Trollen gelernt. Er sah, was die anderen Häuptlinge nicht sehen wollten: dass die {link:trolls}Trolle{/link} die Stämme einen nach dem anderen vernichten würden. Er brachte sie mit allen Mitteln zusammen, die er hatte. Manche gewann er durch Heirat, manche durch Versprechen von Land und Reichtum, und manche besiegte er in der Schlacht. Die Besiegten demütigte er nicht. Er machte ihre Häuptlinge zu seinen Generälen, und so wurden sie seine treuesten Männer.]=],
		},
		{
			title = "Strom",
			text = [=[Thoradin legte seine {link:capital-city}Hauptstadt{/link} auf die trockenen Ebenen des Hochlands, fern der dichten Wälder, in denen die {link:trolls}Trolle{/link} ihre Hinterhalte legten. Die Festung {link:stromgarde-keep}Strom{/link} wurde zu einem Ort der Zuflucht, und {link:humans}Menschen{/link} kamen vom ganzen Kontinent zu ihr. Hier lernte die Menschheit auch zum ersten Mal die arkanen Künste.]=],
		},
		{
			title = "Die Trollkriege",
			text = [=[Als die Amani über {link:quel-thalas}Quel'Thalas{/link} herfielen, schickten die Elfen Gesandte nach {link:stromgarde-keep}Strom{/link}. Sie versprachen, hundert {link:humans}Menschen{/link} die Wege der Magie zu lehren, im Tausch gegen die Schwerter Arathors. Thoradin nahm an. Sein Heer schlug die {link:trolls}Trolle{/link} im Süden der Elfenlande und lockte sie in die Ausläufer des Alteracgebirges, wo die Elfen und die neuen menschlichen Magier von der anderen Seite über sie herfielen. Die Amani wurden zerschlagen. Aus Dankbarkeit schworen die Elfen Thoradins Linie einen Eid der Freundschaft.]=],
		},
		{
			title = "Das Vermächtnis",
			text = [=[Thoradin wünschte, dass {link:stromgarde-keep}Strom{/link} das Herz seines Reiches bliebe, und er fürchtete ein zu weit ausgedehntes Reich. Nach ihm zog sein Volk dennoch hinaus und gründete {link:dalaran}Dalaran{/link}, {link:gilneas}Gilneas{/link}, {link:kul-tiras}Kul Tiras{/link}, {link:alterac-mountains}Alterac{/link} und Lordaeron. Strom verfiel. Schließlich verließ der Letzte seiner Blutlinie die Stadt und segelte nach Süden, um ein neues Königreich zu gründen. Viele Jahrhunderte später führte {link:anduin-lothar}Anduin Lothar{/link}, der Letzte dieser Linie, die {link:alliance}Allianz{/link} von {link:lordaeron}Lordaeron{/link} im Zweiten Krieg.]=],
		},
		{
			title = "Nicht überliefert",
			text = [=[Die Geschichtsschreibung sagt wenig über Thoradins eigene Familie, seine letzten Jahre oder seinen Tod. Dieser Eintrag stellt darüber keine Vermutungen an.]=],
		},
	},
	chapters = {
		{
			title = "Das Siegel von Thoradin",
			hint = [=[Folgt dem zerbrochenen Siegel, das den Namen des ersten Königs trägt.]=],
			text = [=[Unter den Siegeln, die das Grab der Trollbanes schützen, ist eines nach Thoradin benannt. Prinz {link:prince-galen-trollbane}Galen{/link} zerbrach es und verstreute seine Stücke unter seinen letzten Verteidigern. Die Stücke wurden von ihren Leichen genommen, und ein Trollschamane der {link:horde}Horde{/link} fügte sie wieder zusammen. Der Name des ersten Königs war zu einem Schlüssel in den Händen der {link:trolls}Trolle{/link} geworden, die sein Volk einst besiegt hatte.]=],
		},
	},
	mentions = {
		{ text = "Das zerbrochene Siegel" },
		{ text = "Siegel von Thoradin" },
	},
	bonds = {
		{ id = "arathor", name = "Arathor", note = "die Nation, die er gründete" },
		{ id = "anduin-lothar", name = "Anduin Lothar", note = "der Letzte seiner Linie" },
		{ id = "thoradin-s-wall", name = "Thoradinswall", note = "trägt seinen Namen" },
		{ id = "stromgarde-keep", name = "Burg Stromgarde", note = "einst seine Hauptstadt Strom" },
	},
})

Translate("deDE", "thoras-trollbane", {
	title = "Thoras Trollbane",
	subtitle = "Verstorbener König von Stromgarde",
	allegiance = "Königreich Stromgarde · Haus Trollbane",
	aliases = { "Thoras", "König Thoras" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Thoras Trollbane war der König von {link:stromgarde-keep}Stromgarde{/link}, Erbe des alten Hauses, das die Stadt beherrscht, seit die Königslinie Arathors sie verließ. Er war ein Kriegerkönig in einem Land harter Soldaten. Nun ist er tot, und sein Königreich ist mit ihm gestorben. Er liegt in einem versiegelten Grab im Sanktum hinter der Kapelle Stromgardes, das Schwert seines Hauses an seiner Seite.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Thoras war einer der Herrscher, die die {link:alliance}Allianz{/link} von {link:lordaeron}Lordaeron{/link} gegen die {link:horde}Horde{/link} aufstellten. Sein Haus stammt von Ignaeus ab, dem General der {link:troll-wars}Trollkriege{/link}, dessen Klinge {link:trol-kalar}Trol'kalar{/link} der Familie ihren Namen einbrachte. Für die {link:trolls}Trolle{/link} Azeroths ist der Name Trollbane noch immer ein Fluch.]=],
		},
		{
			title = "Taten",
			text = [=[• Er führte {link:stromgarde-keep}Stromgarde{/link} im {link:second-war}Zweiten Krieg{/link} in die {link:alliance}Allianz von Lordaeron{/link}.
• Nach dem Krieg, als die Allianz über die {link:internment-camps}Internierungslager{/link} und ihre Kosten stritt, führte er Stromgarde aus ihr heraus.
• Er wurde mit {link:trol-kalar}Trol'kalar{/link}, dem Schwert des Ignaeus, zur Ruhe gebettet.]=],
		},
		{
			title = "Nicht überliefert",
			text = [=[Keine Chronik dieser Tage verzeichnet, wie Thoras Trollbane starb. Sein Volk sagt nur, dass er fort ist.]=],
		},
	},
	chapters = {
		{
			title = "Das Grab im Sanktum",
			hint = "Tretet vor das Grab des letzten Königs von Stromgarde.",
			text = [=[Das Grab von König Thoras liegt hinter der Kapelle des Viertels der Verteidiger, bewacht von Hütern des Hauses. Seine Vorderseite ist mit Linien beschnitzt, die keine Hand ohne die Siegel öffnen kann, die sein Sohn verstreute. Im Griff steinerner Hände auf dem Grab liegt {link:trol-kalar}Trol'kalar{/link}.]=],
		},
	},
	mentions = {
		{ text = "Trollbane, die Nachricht von seinem Tod" },
		{ text = "{link:trol-kalar}Trol'kalar{/link}" },
	},
	bonds = {
		{ id = "prince-galen-trollbane", name = "Prinz Galen Trollbane", note = "sein Sohn" },
		{ id = "terenas-menethil", name = "Terenas Menethil", note = "sein Verbündeter in der Allianz" },
		{ id = "trol-kalar", name = "Trol'kalar", note = "das Schwert seines Hauses" },
	},
})

Translate("deDE", "trol-kalar", {
	title = "Trol'kalar",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Trol'kalar ist das uralte Schwert des Hauses Trollbane. Sein Name bedeutet in der Sprache der {link:trolls}Trolle{/link} selbst Trolltöter. Es wurde in den Kriegen Arathors von Lord Ignaeus von {link:stromgarde-keep}Strom{/link} geführt, dem gefürchtetsten Feind, dem die Trolle je gegenüberstanden, und es gab seinem Haus den Namen.]=],
		},
		{
			title = "Das Grab",
			text = [=[Als {link:thoras-trollbane}König Thoras{/link} starb, wurde Trol'kalar in sein Grab im Sanktum hinter der Kapelle Stromgardes gelegt, gehalten im Griff steinerner Hände. Das Grab wurde mit Schutzzaubern versiegelt, die nur einem Siegel gehorchen. Prinz {link:prince-galen-trollbane}Galen{/link} teilte dieses Siegel in vier: das Siegel von {link:stromgarde-keep}Strom{/link}, das Siegel von {link:thoradin}Thoradin{/link}, das Siegel von {link:arathor}Arathor{/link} und das Siegel von Trollbane. Eines fiel mit der Stadt an das {link:syndicate}Syndikat{/link}. Die anderen gab er seinen Soldaten, seinem Anführer der Reiterei und sich selbst. Zusammengefügt werden die vier zu einem, dem Siegel des Ignaeus.]=],
		},
		{
			title = "In der Gegenwart",
			text = [=[{link:vol-jin}Vol'jin{/link} von den {link:darkspear-trolls}Darkspear{/link} will das Schwert. Er hat den Jäger {link:zengu}Zengu{/link} nach {link:hammerfall}Hammerfall{/link} geschickt, um es zu holen, damit der Trolltöter von {link:stromgarde-keep}Strom{/link} gegen die Gurubashitrolle von {link:zul-gurub}Zul'Gurub{/link} gewendet werden kann.]=],
		},
	},
})

Translate("deDE", "witherbark-trolls", {
	title = "Witherbarktrolle",
	aliases = { "Witherbark", "Witherbarktrolle", "Stamm der Witherbark" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die {link:witherbark-village}Witherbark{/link} sind ein Stamm von {link:trolls}Waldtrollen{/link}, die im Südosten des Arathihochlands leben. Ihr Dorf steht dort zwischen den Hügeln, mit Höhlen dahinter, in denen sich ihre Kriegsanführer versammeln. Trolle haben seit den Tagen Thoradins gegen die {link:humans}Menschen{/link} von {link:stromgarde-keep}Strom{/link} gekämpft, und die Witherbark tragen diesen Krieg noch immer im Herzen.]=],
		},
		{
			title = "Ihre Bräuche",
			text = [=[Der Stamm hat Axtwerfer, Kopfjäger, Berserker und Hexendoktoren, die Medizinbeutel und Amulette aus Blutstein tragen. Seine Schattenjäger erhalten ein besonderes Messer, wenn sie die Riten ihres Übergangs vollenden. Zwei Kriegsanführer, Zalas {link:witherbark-village}Witherbark{/link} und Nimar der Schlächter, führen sie in den Krieg.]=],
		},
		{
			title = "In der Gegenwart",
			text = [=[Die {link:witherbark-village}Witherbark{/link} kämpften einst an der Seite der {link:orcs}Orcs{/link}, und dann verließen sie sie. Nun haben sie sich mit den Felsfaustogern verbündet, um die {link:horde}Horde{/link} aus {link:hammerfall}Hammerfall{/link} zu vertreiben. Ihre Kämpfer teilen den Ogerhügel {link:boulder-gor}Fels'gor{/link}, und Berserker des Stammes stehen an der Seite der {link:ogres}Oger{/link} in den Ruinen Stromgardes. {link:drum-fel}Drum Fel{/link} aus Hammerfall hat sie zum ersten Ziel seines Krieges gemacht.]=],
		},
	},
})

Translate("deDE", "boulderfist-ogres", {
	title = "Felsfaustoger",
	aliases = { "Felsfäuste", "Felsfaustoger", "Klan der Felsfäuste" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Felsfäuste sind der größte Klan von {link:ogres}Ogern{/link} im {link:arathi-highlands}Arathihochland{/link}. Sie halten den Hügel {link:boulder-gor}Fels'gor{/link}, die Höhlen der {link:boulderfist-hall}Halle der Felsfäuste{/link} und einen großen Teil der zerstörten Stadt {link:stromgarde-keep}Stromgarde{/link}. Keine Chronik verzeichnet, wann sie ins Hochland kamen.]=],
		},
		{
			title = "Ihre Bräuche",
			text = [=[Sie sind Rohlinge, Vollstrecker, Schläger und Lords, mit Magiern und Schamanen, die gelernt haben, die geplünderten Schätze zu nutzen. Ihre Schamanen schätzen die azurblauen Achate, die aus dem Turm von {link:arathor}Arathor{/link} geraubt wurden. In der {link:boulderfist-hall}Halle der Felsfäuste{/link} schleudert der Ogermagier {link:kor-gresh-coldrage}Kor'gresh Coldrage{/link} Eis aus einem gestohlenen Zauberstab. In {link:stromgarde-keep}Stromgarde{/link} befehligt der {link:ogres}Oger{/link} {link:or-kalar}Or'Kalar{/link} sie im Namen Mug'thols, eines Kriegsherrn, der nicht aus dem Hochland stammt.]=],
		},
		{
			title = "In der Gegenwart",
			text = [=[Die Felsfäuste kämpfen gegen die Soldaten Stromgardes und das {link:syndicate}Syndikat{/link} um die Ruinen der Stadt, und sie haben sich mit den Witherbarktrollen gegen {link:hammerfall}Hammerfall{/link} verbündet. Kovork, Molok der Zermalmer, {link:ruul-eagletalon}Ruul{/link} Onestone und Foulbelly sind unter ihren Häuptlingen gefürchtet.]=],
		},
	},
})

Translate("deDE", "drywhisker-kobolds", {
	title = "Trockenstoppelkobolde",
	aliases = { "Trockenstoppel", "Trockenstoppelkobolde" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Trockenstoppel sind ein Stamm von {link:kobolds}Kobolden{/link}, die in der {link:drywhisker-gorge}Schlucht der Trockenstoppel{/link} im äußersten Nordosten des Hochlands graben. Sie sind Vermesser und Gräber, und unter ihnen wirkt ein Geomant namens Flintdagger, der das Feuer beherrscht.]=],
		},
		{
			title = "Die Splitter",
			text = [=[Die Trockenstoppel sind nicht nur Bergleute. Tief in ihrer Schlucht bewachen sie eine Gruppe schillernder Kristallsplitter, und sie tragen Partikel einer seltsamen Macht bei sich. Das Wesen, das gebunden unter dem Hochland liegt, nennt sie Verbündete der Riesen, die es gefangen halten. Drei von ihnen gehen an der Seite des Steinwächters {link:fozruk}Fozruk{/link} selbst. Niemand weiß, was die Riesen den Kobolden für ihre Dienste gegeben haben, oder ob die {link:kobolds}Kobolde{/link} überhaupt verstehen, wem sie dienen.]=],
		},
	},
})

Translate("deDE", "league-of-arathor", {
	title = "Der Bund von Arathor",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Der Bund von Arathor ist die Streitmacht dessen, was vom Königreich {link:stromgarde-keep}Stromgarde{/link} geblieben ist. Seine Soldaten sind die Erben eines stolzen Reiches, dessen {link:capital-city}Hauptstadt{/link} nun von Ogern und Banditen gehalten wird. Sie haben geschworen, das Hochland für das Volk von Stromgarde und für die {link:alliance}Allianz{/link} zurückzugewinnen.]=],
		},
		{
			title = "Ihre Sache",
			text = [=[Der Bund schlägt sein Lager in der Zuflucht unter {link:field-marshal-oslight}Feldmarschall Oslight{/link} auf. Seine erste Schlacht gilt dem {link:arathi-basin}Arathibecken{/link}, einem fruchtbaren Tal voller Höfe, Minen, Schmieden und Wälder. Der Bund will die Reichtümer des Beckens für seine Verbündeten in {link:stormwind-city}Stormwind{/link} beanspruchen und durch Stormwind für die ganze {link:alliance}Allianz{/link}. Seine Soldaten halten Trollbanes Halle am Rand des Tals, benannt nach dem Königshaus von {link:stromgarde-keep}Stromgarde{/link}.]=],
		},
		{
			title = "In der Gegenwart",
			text = [=[Der Bund steht im Becken den Entweihten der Verlassenen gegenüber. Sein Versorgungsoffizier Samuel Hawke schickt Vorräte an jene, die kämpfen, und seine Unteroffiziere drängen jeden Soldaten, zuzuschlagen, bevor der Feind es kann.]=],
		},
	},
})

Translate("deDE", "defilers", {
	title = "Die Entweihten",
	aliases = { "Entweihte", "Entweihte der Verlassenen" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Entweihten sind Elitetruppen der {link:forsaken}Verlassenen{/link}, ins {link:arathi-highlands}Arathihochland{/link} gesandt unter dem wachsamen Auge von {link:varimathras}Varimathras{/link}. Sie kämpfen gegen den Bund von {link:arathor}Arathor{/link} um das {link:arathi-basin}Arathibecken{/link}. Ihr Ziel ist nicht der Krieg der {link:orcs}Orcs{/link}, sondern der ihrer eigenen Königin: die {link:humans}Menschen{/link} des Nordens von ihren zwergischen Verbündeten im Süden abzuschneiden und die Reichtümer des Beckens für {link:undercity}Undercity{/link} an sich zu reißen.]=],
		},
		{
			title = "Ihr Lager",
			text = [=[Die Entweihten haben ihr Hauptquartier in {link:hammerfall}Hammerfall{/link}, neben den {link:orcs}Orcs{/link} und Trollen des Außenpostens, unter {link:deathmaster-dwire}Todesmeister Dwire{/link}. Im Becken halten sie die entweihte Feste. Ihr Versorgungsoffizier Rutherford Twing schickt Vorräte an jene, die für sie kämpfen, und Todespirscher Mortis dient an Dwires Seite.]=],
		},
		{
			title = "In der Gegenwart",
			text = [=[{link:deathmaster-dwire}Dwire{/link} glaubt, dass selbst das kleine Lager der Zuflucht eines Tages die {link:horde}Horde{/link} bedrohen könnte. Die Entweihten wollen sicherstellen, dass {link:arathi-highlands}Arathi{/link} nie wieder eine Heimat für {link:humans}Menschen{/link} wird.]=],
		},
	},
})
